import javax.crypto.spec.SecretKeySpec;","reason":"Import the AndroidKeyStore APIs and Java security types needed to create, reload, and validate the persistent generated current wrapping key." ,"symbol":"MasterKey imports"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","original_code":"    private static final int ITERATIONS = 100000;
    private static final int BYTES = 32;","edit_kind":"constant","corrected_code":"    private static final int ITERATIONS = 100000;
    private static final int BYTES = 32;
    private static final String CURRENT_WRAPPING_KEY_ID = "currentMasterKey";

    private static SecretKey getCurrentWrappingKey(String wrappingKeyId, boolean create)
            throws NoSuchAlgorithmException, InvalidKeyException, IOException {
        if (!CURRENT_WRAPPING_KEY_ID.equals(wrappingKeyId)) {
            throw new InvalidKeyException("Unknown current wrapping key identity");
        }

        try {
            KeyStore keyStore = KeyStore.getInstance("AndroidKeyStore");
            keyStore.load(null);
            Key storedKey = keyStore.getKey(wrappingKeyId, null);
            if (storedKey != null) {
                if (!(storedKey instanceof SecretKey)) {
                    throw new InvalidKeyException("Current wrapping key is not a secret key");
                }
                return (SecretKey) storedKey;
            }

            if (!create) {
                throw new InvalidKeyException("Current wrapping key is unavailable");
            }

            KeyGenerator keyGenerator = KeyGenerator.getInstance(
                    KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore");
            keyGenerator.init(new KeyGenParameterSpec.Builder(wrappingKeyId,
                    KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                    .setRandomizedEncryptionRequired(true)
                    .build());
            return keyGenerator.generateKey();
        } catch (KeyStoreException | NoSuchProviderException | CertificateException e) {
            throw new InvalidKeyException("Unable to resolve current wrapping key", e);
        } catch (InvalidAlgorithmParameterException e) {
            throw new InvalidKeyException("Unable to create current wrapping key", e);
        } catch (UnrecoverableKeyException e) {
            throw new InvalidKeyException("Unable to access current wrapping key", e);
        }
    }","reason":"Define the shared current wrapping-key identity and its persistent AndroidKeyStore resolver. Writes may create the key on first use; reads must reload an existing key and fail rather than creating a non-decrypting replacement.","symbol":"MasterKey current wrapping-key resolution"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","original_code":"    private MasterKey(PBEKeySpec spec) throws NoSuchAlgorithmException,
            IllegalBlockSizeException, InvalidKeyException, BadPaddingException,
            NoSuchPaddingException, InvalidKeySpecException, IOException {
        SecretKeyFactory skf = getSecretKeyFactory();
        SecretKey pwd = skf.generateSecret(spec);

        byte[] raw = new byte[pwd.getEncoded().length];
        new SecureRandom().nextBytes(raw);
        SecretKey key = new SecretKeySpec(raw, "AES");

        mEncryptedKey = EncryptedKey.encrypt(pwd, key);
        mIterations = spec.getIterationCount();
        mAlgorithm = skf.getAlgorithm();
        mSalt = spec.getSalt();
    }","edit_kind":"method","corrected_code":"    private MasterKey(PBEKeySpec spec) throws NoSuchAlgorithmException,
            IllegalBlockSizeException, InvalidKeyException, BadPaddingException,
            NoSuchPaddingException, InvalidKeySpecException, IOException {
        SecretKeyFactory skf = getSecretKeyFactory();

        byte[] raw = new byte[BYTES];
        new SecureRandom().nextBytes(raw);
        SecretKey key = new SecretKeySpec(raw, "AES");

        mEncryptedKey = EncryptedKey.encrypt(
                getCurrentWrappingKey(CURRENT_WRAPPING_KEY_ID, true), key,
                CURRENT_WRAPPING_KEY_ID);
        mIterations = spec.getIterationCount();
        mAlgorithm = skf.getAlgorithm();
        mSalt = spec.getSalt();
    }","reason":"Route newly created MasterKey records through the generated persistent current wrapping key and its identity. PBKDF2 metadata is retained so existing legacy records remain resolvable, but the PBKDF2 result no longer reaches the current encryption path.","symbol":"MasterKey(PBEKeySpec)"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","original_code":"    private SecretKey decrypt(PBEKeySpec spec) throws NoSuchAlgorithmException,
            InvalidKeySpecException, IllegalBlockSizeException, InvalidKeyException,
            BadPaddingException, InvalidAlgorithmParameterException, NoSuchPaddingException,
            IOException {
        SecretKeyFactory skf = SecretKeyFactory.getInstance(mAlgorithm);
        SecretKey pwd = skf.generateSecret(spec);
        return mEncryptedKey.decrypt(pwd);
    }","edit_kind":"method","corrected_code":"    private SecretKey decrypt(PBEKeySpec spec) throws NoSuchAlgorithmException,
            InvalidKeySpecException, IllegalBlockSizeException, InvalidKeyException,
            BadPaddingException, InvalidAlgorithmParameterException, NoSuchPaddingException,
            IOException {
        if (mEncryptedKey.isCurrentRecord()) {
            return mEncryptedKey.decrypt(null,
                    getCurrentWrappingKey(mEncryptedKey.getWrappingKeyId(), false));
        }

        SecretKeyFactory skf = SecretKeyFactory.getInstance(mAlgorithm);
        SecretKey legacyKey = skf.generateSecret(spec);
        return mEncryptedKey.decrypt(legacyKey, null);
    }","reason":"Select the generated AndroidKeyStore key only for discriminator-bearing current records. Records without the discriminator retain the PBKDF2 derivation and pass it as the legacy decrypt key, preserving legacy encrypted-record compatibility.","symbol":"MasterKey.decrypt(PBEKeySpec)"}],"manual_review_required":true,"provided_contracts":["MasterKey.generate(String) preserves its public signature and writes current encrypted records through EncryptedKey.encrypt(SecretKey, SecretKey, String) using the persistent identity "currentMasterKey".","MasterKey current-record reads use EncryptedKey.getWrappingKeyId() to reload the persistent AndroidKeyStore key and call EncryptedKey.decrypt(null, currentKey).","MasterKey legacy-record reads continue to derive the PBKDF2 key from the persisted algorithm, salt, and iteration count and call EncryptedKey.decrypt(legacyKey, null)."],"required_contracts":["EncryptedKey must retain legacy two-argument encryption and represent it without a current-record discriminator.","EncryptedKey current-record encryption must accept "currentMasterKey", retain provider-generated cipher parameters, and decrypt version-1 records using the second argument of decrypt(SecretKey, SecretKey).","The dedicated instrumentation test must verify MasterKey legacy-read compatibility and current AndroidKeyStore-backed round trips without caller-supplied GCM parameters."],"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","required_tests":["Run Android instrumentation coverage verifying MasterKey.generate/decrypt round trips through the current "currentMasterKey" AndroidKeyStore lifecycle.","Verify a legacy representation created with EncryptedKey.encrypt(legacyKey, plaintext) remains decryptable through MasterKey's PBKDF2 legacy branch.","Verify missing or unknown current wrapping-key identities fail current-record reads rather than creating a replacement key."]}
